import clsx from 'clsx';
import React from 'react';

import { magnifier, magnifierFontStyles, right } from './Magnifier.sty.js';
import { getTextWidth } from '../../../../../typography/utils.js';
import { useOverlaysEvents } from '../../../hooks/useOverlaysEvents.js';
import { useMagnifierPosition } from '../hooks/useMagnifierPosition.js';

export function RightMagnifier(props: {
  label: string;
  mouseY: number;
  offset: number;
}) {
  const { label, mouseY, offset } = props;

  const { chartBounds } = useOverlaysEvents();

  const { magnifierPosition: top, magnifierRef } = useMagnifierPosition(
    mouseY,
    chartBounds?.top ?? 0,
    chartBounds?.bottom ?? 0,
    'vertical',
  );

  const textWidth = getTextWidth(label, magnifierFontStyles);

  const left = chartBounds?.right ?? 0 + offset;

  return (
    <div
      data-testid="right-y-axis-magnifier"
      ref={magnifierRef}
      className={clsx(magnifier, right)}
      style={{ top, left, width: textWidth }}
    >
      {label}
    </div>
  );
}
